effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    float t = floor(acTime*speed*8.0);
    vec2 uv = acScreenNorm;
    float row = floor(uv.y/blockSize);
    float r = rand(vec2(row, t));
    float shift = 0.0;
    if(r > 1.0-amount*0.6){
        shift = (rand(vec2(row*1.7, t))-0.5) * amount * 0.3;
    }
    uv.x += shift;
    float rs = rgbShift*0.01*(r>0.5?1.0:0.0);
    float cr = texture2DCv(inputImg.texture, uv+vec2(rs,0.0)).r;
    vec4 cg = texture2DCv(inputImg.texture, uv);
    float cb = texture2DCv(inputImg.texture, uv-vec2(rs,0.0)).b;
    gl_FragColor = vec4(cr,cg.g,cb,cg.a);
}
